// Beat sheet (internal clock = frame + 2, 30fps, speed 1):
//   0–12   whip-pan lands on an extreme close-up of line 1 (motion-streak ghosts)
//  12–26   hard cut: line 2 whips in from the left, tighter push
//  26–37   hard cut: line 3 slams down from 1.7×; frame 31 is the impact frame
//          (one inverted frame) and the camera shakes
//  37–46   whip-zoom out to the full poster framing
//  44–62   the "beam" spotlight band swings in from the left and parks across
//          the stack; the type inside it knocks out to the stage colour
//  52–63   record label + record slam in beside the name, then the finishes stat
//  64–74   the nickname wipes in beside the last line; billing and logo rise
//  80–     fight-poster hold
const SLAM = Easing.bezier(0.12, 0.9, 0.25, 1);
const OUT = Easing.bezier(0.22, 1, 0.36, 1);
const INOUT = Easing.bezier(0.7, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "beam": bg #02030a, [#f4f7ff, #8fb4ff, #3d5bff, #1a1660].
const BEAM = ["#F4F7FF", "#8FB4FF", "#3D5BFF", "#1A1660"] as const;

const THEMES = {
  dark: {
    stage: "#0A0A0B",
    ink: "#F3F2EF",
    dim: "#8A8990",
    knock: "#0A0A0B",
    band: `linear-gradient(90deg, ${BEAM[2]} 0%, ${BEAM[1]} 30%, ${BEAM[0]} 50%, ${BEAM[1]} 70%, ${BEAM[2]} 100%)`,
    edge: BEAM[3],
    stat: `linear-gradient(180deg, ${BEAM[0]} 10%, ${BEAM[1]} 55%, ${BEAM[2]} 100%)`,
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    dim: "#7E7D77",
    knock: "#FFFFFF",
    band: `linear-gradient(90deg, ${BEAM[3]} 0%, ${BEAM[2]} 34%, #5F7BFF 50%, ${BEAM[2]} 66%, ${BEAM[3]} 100%)`,
    edge: BEAM[1],
    stat: `linear-gradient(180deg, ${BEAM[2]} 0%, #2A2F9E 60%, ${BEAM[3]} 100%)`,
  },
} as const;

// Oswald 500 metrics (em): cap height 0.81, cap top sits 0.142 below a
// line-height-1 box, average uppercase advance ~0.5.
const CAP = 0.81;
const CAP_TOP = 0.142;
const ADV = 0.5;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** Decaying camera shake that starts at `at`, stepped per frame. */
function shake(t: number, at: number, len: number, amp: number) {
  const d = Math.floor(t - at);
  if (d < 0 || d >= len) return { x: 0, y: 0 };
  const k = (1 - d / len) ** 2;
  return {
    x: amp * k * Math.sin(d * 2.4 + 0.6),
    y: amp * 0.6 * k * Math.cos(d * 3.1 + 0.3),
  };
}

interface Cam {
  cx: number;
  cy: number;
  s: number;
  dx: number;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function WalkoutNameBase(props: WalkoutNameProps) {
  const {
    name = DEFAULT_NAME,
    nickname = "Ships before lunch",
    record = "12–0",
    finishes = "12 KO",
    recordLabel = "Pro record",
    billing = "Main event · Tonight",
    bandWidth = 0.19,
    impact = 1,
    logo,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = oswald,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed + PREROLL;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    walkoutNameTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.stage);
  const u = Math.min(W / 1280, H / 720);

  const lines = walkoutLines(name);
  const n = Math.max(1, lines.length);

  // ── Poster layout (world coordinates = poster pixels) ─────────────────────
  const x0 = 64 * u;
  const gap = 16 * u;
  const longest = Math.max(...lines.map((l) => l.length), 1);
  const nameFs = Math.min(
    200 * u,
    (0.52 * W) / (longest * ADV),
    (0.72 * H - (n - 1) * gap) / (n * CAP),
  );
  const capH = CAP * nameFs;
  const stackH = n * capH + (n - 1) * gap;
  const top = (H - stackH) / 2 + 2 * u;
  const lineTop = (i: number) => top + i * (capH + gap);
  const lineW = (i: number) => lines[i].length * ADV * nameFs;
  const lineCenter = (i: number) => ({
    x: x0 + lineW(i) / 2,
    y: lineTop(i) + capH / 2,
  });

  // ── Shots ─────────────────────────────────────────────────────────────────
  // One shot per line: line i becomes visible when its shot starts.
  // The schedule counts scene frames; `t` runs `PREROLL` ahead of them.
  const shots = Array.from({ length: n }, (_, i) => tl.get(`shot:${i}`));
  const shotAt = shots.map((e) => e.start + PREROLL);
  const lastShot = shotAt[n - 1];
  const lastEl = shots[n - 1];
  const whipEl = tl.get("whip-out");
  const whipOut = whipEl.start + PREROLL;
  const bandEl = tl.get("band");
  const recordEl = tl.get("record");
  const finishEl = tl.get("finishes");
  const RECORD_AT = recordEl.start + PREROLL;
  const FINISH_AT = finishEl.start + PREROLL;
  const BAND_AT = bandEl.start + PREROLL;
  const poster: Cam = { cx: W / 2, cy: H / 2, s: 1, dx: 0 };

  const framing = (i: number): Cam => {
    const p = lineCenter(i);
    const s = Math.min(2.4, (0.62 * W) / Math.max(lineW(i), 1));
    return { cx: p.x, cy: p.y, s: Math.max(1.45, s), dx: 0 };
  };

  const camAt = (tt: number): Cam => {
    if (tt >= whipOut) {
      const p = INOUT(ramp(tt, whipOut, whipEl.length));
      const f = framing(n - 1);
      return {
        cx: interpolate(p, [0, 1], [f.cx, poster.cx]),
        cy: interpolate(p, [0, 1], [f.cy, poster.cy]),
        s: interpolate(p, [0, 1], [f.s * 1.04, 1]),
        dx: 0,
      };
    }
    let i = 0;
    for (let k = 0; k < n; k++) if (tt >= shotAt[k]) i = k;
    const f = framing(i);
    const local = tt - shotAt[i];
    const push = 1 + 0.04 * ramp(local, 0, shots[i].beat("push"));
    // Lines 1 and 2 whip in (from the right, then from the left); the last
    // line lands in place and slams instead.
    const whipping = i < n - 1 || n === 1;
    const dir = i % 2 === 0 ? 1 : -1;
    const dx = whipping
      ? dir * 0.95 * W * (1 - OUT(ramp(local, 0, shots[i].beat("whip"))))
      : 0;
    return { ...f, s: f.s * push, dx };
  };

  // Ghosts only during whips, never across a hard cut.
  const shotStart = (tt: number) => {
    if (tt >= whipOut) return whipOut;
    let s0 = 0;
    for (let k = 0; k < n; k++) if (tt >= shotAt[k]) s0 = shotAt[k];
    return s0;
  };
  const cam = camAt(t);
  const prev = camAt(t - 1);
  const speedPx =
    Math.abs(cam.dx - prev.dx) +
    Math.abs(W / 2 - cam.s * cam.cx - (W / 2 - prev.s * prev.cx)) +
    Math.abs(cam.s - prev.s) * W * 0.5;
  const ghosts = speedPx > 18 * u ? [0.32, 0.2, 0.12, 0.07] : [];

  // ── Impact on the last line ───────────────────────────────────────────────
  const slamP = SLAM(ramp(t, lastShot, lastEl.beat("slam")));
  const lastScale = n > 1 ? 1.7 - 0.7 * slamP : 1;
  const hit = lastShot + lastEl.beat("slam");
  const inverted = n > 1 && t >= hit && t < hit + speed;
  const s1 =
    n > 1
      ? shake(t, hit, lastEl.beat("shake"), 14 * u * impact)
      : { x: 0, y: 0 };
  const s2 = shake(
    t,
    RECORD_AT + recordEl.length,
    recordEl.beat("shake"),
    5 * u * impact,
  );
  const s3 = shake(
    t,
    FINISH_AT + finishEl.length,
    finishEl.beat("shake"),
    5 * u * impact,
  );
  const shX = s1.x + s2.x + s3.x;
  const shY = s1.y + s2.y + s3.y;

  // ── Spotlight band (world coordinates, leaning right) ─────────────────────
  const bandW = bandWidth * W;
  const lean = Math.tan((20 * Math.PI) / 180);
  const bandIn = OUT(ramp(t, BAND_AT, bandEl.length));
  const bandDrift = interpolate(
    t,
    [BAND_AT + bandEl.length, BAND_AT + bandEl.beat("driftEnd")],
    [0, 0.03],
    CLAMP,
  );
  const bandCx =
    interpolate(bandIn, [0, 1], [-0.35 * W, 0.4 * W]) + bandDrift * W;
  // The band is laid out where it parks; the swing and the drift are a
  // transform, since layout would step its painted edges a pixel at a time.
  const bandRest = 0.4 * W;
  const bandPoly = (cx: number, w: number) => {
    const ext = H * 0.4;
    const yT = -ext;
    const yB = H + ext;
    const xAt = (y: number) => cx + (H / 2 - y) * lean;
    return `polygon(${xAt(yT) - w / 2}px ${yT}px, ${xAt(yT) + w / 2}px ${yT}px, ${xAt(yB) + w / 2}px ${yB}px, ${xAt(yB) - w / 2}px ${yB}px)`;
  };
  const showBand = t >= BAND_AT;

  // ── Stats column ──────────────────────────────────────────────────────────
  const colX = Math.max(
    x0 + Math.max(...lines.map((_, i) => lineW(i))) + 70 * u,
    0.6 * W,
  );
  const statFs = 196 * u;
  const labelFs = 19 * u;
  const recordTop = top + 46 * u;
  const finishTop = recordTop + CAP * statFs + 34 * u;
  const recP = SLAM(ramp(t, RECORD_AT, recordEl.length));
  const finP = SLAM(ramp(t, FINISH_AT, finishEl.length));
  const ruleP = OUT(
    ramp(t, FINISH_AT + finishEl.beat("ruleAt"), finishEl.beat("rule")),
  );

  // ── Nickname + meta ───────────────────────────────────────────────────────
  const nickFs = 74 * u;
  const lastBase = lineTop(n - 1) + capH;
  const nickX = x0 + lineW(n - 1) + 44 * u;
  const nickEl = tl.get("nickname");
  const metaEl = tl.get("meta");
  const nickP = OUT(ramp(t, nickEl.start + PREROLL, nickEl.length));
  const metaP = OUT(ramp(t, metaEl.start + PREROLL, metaEl.length));

  // Everything that carries text on a transform, in pixels, so the tilt on
  // the shake layer can follow it: the camera, the shake, the slams and the
  // billing and logo rising in.
  const pose = (tt: number) => {
    const cm = camAt(tt);
    const sh = [
      n > 1
        ? shake(tt, hit, lastEl.beat("shake"), 14 * u * impact)
        : { x: 0, y: 0 },
      shake(
        tt,
        RECORD_AT + recordEl.length,
        recordEl.beat("shake"),
        5 * u * impact,
      ),
      shake(
        tt,
        FINISH_AT + finishEl.length,
        finishEl.beat("shake"),
        5 * u * impact,
      ),
    ];
    return [
      W / 2 - cm.s * cm.cx + cm.dx,
      H / 2 - cm.s * cm.cy,
      cm.s * W,
      ...sh.flatMap((v) => [v.x, v.y]),
      (n > 1 ? 1.7 - 0.7 * SLAM(ramp(tt, lastShot, lastEl.beat("slam"))) : 1) *
        W,
      SLAM(ramp(tt, RECORD_AT, recordEl.length)) * W,
      SLAM(ramp(tt, FINISH_AT, finishEl.length)) * W,
      OUT(ramp(tt, metaEl.start + PREROLL, metaEl.length)) * 12 * u,
    ];
  };
  const here = pose(t);
  const before = pose(t - speed);
  const after = pose(t + speed);
  const moving = here.some(
    (v, i) => Math.abs(after[i] - v) > 1e-3 || Math.abs(v - before[i]) > 1e-3,
  );

  const text = (
    s: string,
    fs: number,
    color: string,
    extra?: React.CSSProperties,
  ) => (
    <div
      style={{
        fontFamily,
        fontWeight: 500,
        fontSize: fs,
        lineHeight: 1,
        letterSpacing: "-0.01em",
        color,
        whiteSpace: "nowrap",
        ...extra,
      }}
    >
      {s}
    </div>
  );

  // The name stack, in one colour. Rendered twice: ink, then knocked out
  // to the stage colour inside the band.
  const stack = (ink: string, key: string) => (
    <div key={key} style={{ position: "absolute", inset: 0 }}>
      {lines.map((l, i) => {
        if (t < shotAt[i]) return null;
        const isLast = i === n - 1;
        const k = isLast ? lastScale : 1;
        const p = lineCenter(i);
        return (
          <div
            key={`${i}-${l}`}
            style={{
              position: "absolute",
              left: x0,
              top: lineTop(i) - CAP_TOP * nameFs,
              transform: `scale(${k})`,
              transformOrigin: `${p.x - x0}px ${CAP_TOP * nameFs + capH / 2}px`,
              opacity: isLast ? ramp(t, lastShot, lastEl.beat("show")) : 1,
            }}
          >
            {text(l, nameFs, ink, { letterSpacing: "-0.015em" })}
          </div>
        );
      })}
      {nickP > 0 ? (
        <div
          style={{
            position: "absolute",
            left: nickX,
            top: lastBase - nickFs * 0.86,
            fontFamily: serif,
            fontStyle: "italic",
            fontWeight: 400,
            fontSize: nickFs,
            lineHeight: 1,
            letterSpacing: "-0.01em",
            color: ink,
            whiteSpace: "nowrap",
            clipPath: `inset(-20% ${100 - 100 * nickP}% -20% -5%)`,
            transform: `translateX(${(1 - nickP) * -24 * u}px)`,
          }}
        >
          “{nickname}”
        </div>
      ) : null}
    </div>
  );

  const world = (camera: Cam, opacity: number, key: string) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        width: W,
        height: H,
        transformOrigin: "0 0",
        transform: `translate(${W / 2 - camera.s * camera.cx + camera.dx}px, ${H / 2 - camera.s * camera.cy}px) scale(${camera.s})`,
        opacity,
      }}
    >
      {showBand ? (
        <>
          <div
            style={{
              position: "absolute",
              inset: 0,
              clipPath: bandPoly(bandCx, bandW + 10 * u),
              background: c.edge,
            }}
          />
          <div
            style={{
              position: "absolute",
              left: bandRest - bandW / 2 - 0.5 * H * lean,
              transform: `translateX(${bandCx - bandRest}px)`,
              width: bandW + H * lean,
              top: 0,
              height: H,
              clipPath: `polygon(${H * lean}px 0, 100% 0, calc(100% - ${H * lean}px) 100%, 0 100%)`,
              background: c.band,
            }}
          />
        </>
      ) : null}
      {stack(fg, "ink")}
      {showBand ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            clipPath: bandPoly(bandCx, bandW + 10 * u),
          }}
        >
          {stack(c.knock, "knock")}
        </div>
      ) : null}
    </div>
  );

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: stage,
          filter: inverted ? "invert(1)" : undefined,
        }}
      >
        <ScaleLayer scale={scale}>
          <div
            style={{
              position: "absolute",
              inset: 0,
              // One tilt for the whole poster: the camera's origin is the
              // world's corner, far off screen, so the tilt goes here, about
              // the frame's centre.
              transform: `translate(${shX}px, ${shY}px)${glide(moving)}`,
            }}
          >
            {ghosts.map((op, k) => {
              const tt = Math.max(shotStart(t), t - (k + 1) * 0.5);
              return world(camAt(tt), op, `g${k}`);
            })}
            {world(cam, 1, "main")}

            {/* Stats column: screen space, lands after the whip-out. */}
            {t >= RECORD_AT ? (
              <div
                style={{
                  position: "absolute",
                  left: colX,
                  top: recordTop - 44 * u,
                  display: "flex",
                  alignItems: "center",
                  gap: 12 * u,
                  opacity: ramp(t, RECORD_AT, recordEl.beat("label")),
                  fontFamily,
                  fontWeight: 400,
                  fontSize: labelFs,
                  letterSpacing: "0.28em",
                  textTransform: "uppercase",
                  color: c.dim,
                }}
              >
                <div
                  style={{ width: 22 * u, height: 3 * u, background: accent }}
                />
                {recordLabel}
              </div>
            ) : null}
            {t >= RECORD_AT ? (
              <div
                style={{
                  position: "absolute",
                  left: colX,
                  top: recordTop - CAP_TOP * statFs,
                  transform: `scale(${1.55 - 0.55 * recP})`,
                  transformOrigin: `0 ${CAP_TOP * statFs + (CAP * statFs) / 2}px`,
                  opacity: ramp(t, RECORD_AT, recordEl.beat("show")),
                }}
              >
                {text(record, statFs, fg, {
                  fontVariantNumeric: "tabular-nums",
                })}
              </div>
            ) : null}
            {ruleP > 0 ? (
              <div
                style={{
                  position: "absolute",
                  left: colX,
                  top: finishTop - 18 * u,
                  width: 0.3 * W * ruleP,
                  height: 2 * u,
                  background: c.dim,
                  opacity: 0.5,
                }}
              />
            ) : null}
            {t >= FINISH_AT ? (
              <div
                style={{
                  position: "absolute",
                  left: colX,
                  top: finishTop - CAP_TOP * statFs,
                  transform: `scale(${1.55 - 0.55 * finP})`,
                  transformOrigin: `0 ${CAP_TOP * statFs + (CAP * statFs) / 2}px`,
                  opacity: ramp(t, FINISH_AT, finishEl.beat("show")),
                }}
              >
                {text(finishes, statFs, "transparent", {
                  backgroundImage: c.stat,
                  WebkitBackgroundClip: "text",
                  backgroundClip: "text",
                  paddingRight: 8 * u,
                })}
              </div>
            ) : null}

            {/* Billing top left, logo bottom right. */}
            {metaP > 0 ? (
              <>
                <div
                  style={{
                    position: "absolute",
                    left: x0 + 4 * u,
                    top: 40 * u,
                    display: "flex",
                    alignItems: "center",
                    gap: 12 * u,
                    opacity: metaP,
                    transform: `translateY(${(1 - metaP) * -12 * u}px)`,
                    fontFamily,
                    fontWeight: 400,
                    fontSize: labelFs,
                    letterSpacing: "0.28em",
                    textTransform: "uppercase",
                    color: c.dim,
                  }}
                >
                  <div
                    style={{ width: 9 * u, height: 9 * u, background: accent }}
                  />
                  {billing}
                </div>
                <div
                  style={{
                    position: "absolute",
                    right: x0,
                    bottom: 40 * u,
                    opacity: metaP,
                    transform: `translateY(${(1 - metaP) * 12 * u}px)`,
                  }}
                >
                  {logo ?? <RemocnLogo fontSize={36 * u} color={fg} />}
                </div>
              </>
            ) : null}
          </div>
        </ScaleLayer>
      </div>
    </AbsoluteFill>
  );
}

